document.querySelectorAll('[data-lab="L15-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const rho=root.querySelector('[data-rho]'),count=root.querySelector('[data-count]'),mode=root.querySelector('[data-mode]'),en=root.dataset.lang==='en';function draw(){const r=+rho.value,n=+count.value,matched=Math.sqrt(2*(1-r)/n),unmatched=Math.sqrt(2/n),scale=145;root.querySelector('[data-rho-value]').textContent=r.toFixed(2);root.querySelector('[data-count-value]').textContent=n;for(const [key,v]of[['match',matched],['unmatch',unmatched]]){const bar=root.querySelector('[data-'+key+']'),txt=root.querySelector('[data-'+key+'-text]');bar.setAttribute('height',v*scale);bar.setAttribute('y',315-v*scale);txt.setAttribute('y',300-v*scale);txt.textContent=v.toFixed(4);if(key==='unmatch'){bar.style.display=mode.value==='both'?'':'none';txt.style.display=bar.style.display;root.querySelector('[data-unmatch-label]').style.display=bar.style.display;}}root.querySelector('[data-answer]').textContent=(en?'Matched SE = ':'配对标准误 = ')+matched.toFixed(4)+'; '+(en?'unmatched SE = ':'非配对标准误 = ')+unmatched.toFixed(4)+'. '+(r>0?(en?'Positive covariance reduces variation in the difference.':'正协方差使差值中的共同变化相互抵消。'):r<0?(en?'Negative covariance increases variation in the difference.':'负协方差使差值的变化增大。'):(en?'At zero covariance the expressions coincide.':'协方差为零时，两种表达式相同。'));}rho.addEventListener('input',draw);count.addEventListener('input',draw);mode.addEventListener('change',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{rho.value='.5';count.value='4';mode.value='both';draw();});draw();});